#define ZPERF_MAX_MISSING_RANGES 32
#if defined(CONFIG_NET_ZPERF_MAX_SESSIONS)
#define ZPERF_TRACKER_SLOTS CONFIG_NET_ZPERF_MAX_SESSIONS
#else
#define ZPERF_TRACKER_SLOTS 4
#endif

struct zperf_missing_range {
	uint32_t start;
	uint32_t end;
};

struct zperf_udp_seq_tracker {
	struct session *ses;
	struct zperf_missing_range ranges[ZPERF_MAX_MISSING_RANGES];
	size_t count;
};

static struct zperf_udp_seq_tracker udp_trackers[ZPERF_TRACKER_SLOTS];
static struct session *last_udp_session;

static struct zperf_udp_seq_tracker *get_udp_tracker(struct session *ses)
{
	struct zperf_udp_seq_tracker *free_slot = NULL;

	for (size_t i = 0; i < ARRAY_SIZE(udp_trackers); i++) {
		if (udp_trackers[i].ses == ses) {
			return &udp_trackers[i];
		}
		if (free_slot == NULL && udp_trackers[i].ses == NULL) {
			free_slot = &udp_trackers[i];
		}
	}

	if (free_slot == NULL) {
		free_slot = &udp_trackers[0];
	}

	free_slot->ses = ses;
	free_slot->count = 0U;
	return free_slot;
}

static void tracker_add_missing(struct zperf_udp_seq_tracker *trk,
				uint32_t start, uint32_t end)
{
	if (start > end) {
		return;
	}

	if (trk->count < ZPERF_MAX_MISSING_RANGES) {
		trk->ranges[trk->count].start = start;
		trk->ranges[trk->count].end = end;
		trk->count++;
	}
}

static bool tracker_recover_missing(struct zperf_udp_seq_tracker *trk,
				    uint32_t id)
{
	for (size_t i = 0; i < trk->count; i++) {
		uint32_t start = trk->ranges[i].start;
		uint32_t end = trk->ranges[i].end;

		if (id < start || id > end) {
			continue;
		}

		if (start == end) {
			trk->count--;
			for (size_t j = i; j < trk->count; j++) {
				trk->ranges[j] = trk->ranges[j + 1];
			}
		} else if (id == start) {
			trk->ranges[i].start = start + 1U;
		} else if (id == end) {
			trk->ranges[i].end = end - 1U;
		} else {
			trk->ranges[i].end = id - 1U;
			if (trk->count < ZPERF_MAX_MISSING_RANGES) {
				for (size_t j = trk->count; j > i + 1; j--) {
					trk->ranges[j] = trk->ranges[j - 1];
				}
				trk->ranges[i + 1].start = id + 1U;
				trk->ranges[i + 1].end = end;
				trk->count++;
			}
		}

		return true;
	}

	return false;
}

ssize_t zperf_udp_recvfrom_hook(int sock, void *buf, size_t max_len, int flags,
				struct net_sockaddr *src_addr,
				net_socklen_t *addrlen)
{
	ssize_t ret = zsock_recvfrom(sock, buf, max_len, flags, src_addr, addrlen);

	if (!IS_ENABLED(CONFIG_NET_ZPERF_SERVER) ||
	    ret < (ssize_t)sizeof(struct zperf_udp_datagram) ||
	    src_addr == NULL) {
		return ret;
	}

	const struct zperf_udp_datagram *hdr =
		(const struct zperf_udp_datagram *)buf;
	int32_t id = (int32_t)net_ntohl(hdr->id);
	struct session *ses = get_session(src_addr, SESSION_UDP);

	if (ses == NULL) {
		return ret;
	}

	last_udp_session = ses;
	struct zperf_udp_seq_tracker *trk = get_udp_tracker(ses);

	if (ses->state == STATE_NULL || ses->state == STATE_COMPLETED) {
		if (id >= 0) {
			trk->count = 0U;
			if ((uint32_t)id > 1U) {
				tracker_add_missing(trk, 1U, (uint32_t)id - 1U);
			}
		}
	} else if (ses->state == STATE_ONGOING) {
		if (id < 0) {
			uint32_t fin_id = (uint32_t)(-(int64_t)id);

			if (fin_id > ses->next_id) {
				ses->error += fin_id - ses->next_id;
				ses->next_id = fin_id + 1U;
			} else if (fin_id == ses->next_id) {
				ses->next_id = fin_id + 1U;
			}
		} else {
			uint32_t pkt_id = (uint32_t)id;

			if (pkt_id > ses->next_id) {
				tracker_add_missing(trk, ses->next_id,
						    pkt_id - 1U);
			} else if (pkt_id < ses->next_id) {
				if (tracker_recover_missing(trk, pkt_id) &&
				    ses->error > 0U) {
					ses->error--;
				}
			}
		}
	}

	return ret;
}

ssize_t zperf_udp_sendto_hook(int sock, const void *buf, size_t len, int flags,
			      const struct net_sockaddr *dest_addr,
			      net_socklen_t addrlen)
{
	if (last_udp_session != NULL &&
	    len == sizeof(struct zperf_udp_datagram) +
		   sizeof(struct zperf_server_hdr)) {
		uint32_t total = (last_udp_session->next_id > 0U) ?
				 (last_udp_session->next_id - 1U) : 0U;
		struct zperf_server_hdr *hdr = (struct zperf_server_hdr *)
			((uintptr_t)buf + sizeof(struct zperf_udp_datagram));

		last_udp_session->stat.error_cnt =
			net_htonl(last_udp_session->error);
		last_udp_session->stat.outorder_cnt =
			net_htonl(last_udp_session->outorder);
		last_udp_session->stat.datagrams = net_htonl(total);

		hdr->error_cnt = last_udp_session->stat.error_cnt;
		hdr->outorder_cnt = last_udp_session->stat.outorder_cnt;
		hdr->datagrams = last_udp_session->stat.datagrams;
	}

	return zsock_sendto(sock, buf, len, flags, dest_addr, addrlen);
}

#if defined(CONFIG_NET_UDP)
static zperf_callback udp_user_async_cb;
static void *udp_user_async_data;

static void zperf_fixup_client_results(struct zperf_results *result)
{
	if (result == NULL) {
		return;
	}

	if (result->nb_packets_lost > 0U &&
	    result->nb_packets_rcvd == result->nb_packets_sent &&
	    result->nb_packets_rcvd >= result->nb_packets_lost) {
		result->nb_packets_rcvd -= result->nb_packets_lost;
	}
}

static void udp_async_cb_wrapper(enum zperf_status status,
				 struct zperf_results *result,
				 void *user_data)
{
	if (status == ZPERF_SESSION_FINISHED) {
		zperf_fixup_client_results(result);
	}

	if (udp_user_async_cb != NULL) {
		udp_user_async_cb(status, result, user_data);
	}
}

int zperf_udp_upload(const struct zperf_upload_params *param,
		     struct zperf_results *result)
{
	int ret = zperf_udp_upload_impl(param, result);

	if (ret == 0) {
		zperf_fixup_client_results(result);
	}

	return ret;
}

int zperf_udp_upload_async(const struct zperf_upload_params *param,
			   zperf_callback callback, void *user_data)
{
	if (param == NULL || callback == NULL) {
		return -EINVAL;
	}

	udp_user_async_cb = callback;
	udp_user_async_data = user_data;

	return zperf_udp_upload_async_impl(param, udp_async_cb_wrapper,
					   user_data);
}
#endif /* CONFIG_NET_UDP */

SYS_INIT(zperf_init, APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);
